package local.skyfamily;
import android.graphics.*;import android.os.SystemClock;import android.view.*;import android.webkit.WebView;import android.widget.*;
class PetSprite extends View {
 final CompanionActivity host;final PetState pet;final Paint paint=new Paint(3);boolean active=true;
 PetSprite(CompanionActivity activity,PetState state){super(activity);host=activity;pet=state;setContentDescription("Virtual companion / tap for care");setOnClickListener(v->host.pet());}
 final Runnable tick=new Runnable(){public void run(){if(active&&host.resumed&&isShown()&&getWindowVisibility()==VISIBLE){invalidate();postDelayed(this,140);}}};
 void running(boolean value){active=value;removeCallbacks(tick);if(value&&getVisibility()==VISIBLE)post(tick);}
 protected void onAttachedToWindow(){super.onAttachedToWindow();running(true);}protected void onDetachedFromWindow(){removeCallbacks(tick);super.onDetachedFromWindow();}
 protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(tick!=null)running(active);}
 protected void onDraw(Canvas canvas){pet.tick();float scale=Math.min(getWidth()/32f,getHeight()/30f),time=SystemClock.elapsedRealtime()/1000f;canvas.save();canvas.translate((getWidth()-32*scale)/2,(getHeight()-30*scale)/2);canvas.scale(scale,scale);paint.setStyle(Paint.Style.FILL);float bounce=pet.sleeping?0:(float)Math.sin(time*3)*.8f;canvas.translate(0,bounce);paint.setColor(0xffd8d0bf);canvas.drawOval(new RectF(6,25,26,28),paint);if(pet.stage().equals("Egg")){paint.setColor(0xff93c5b2);canvas.drawOval(new RectF(9,5,23,26),paint);paint.setColor(0xff46675a);canvas.drawRect(12,12,15,15,paint);canvas.drawRect(18,18,21,21,paint);}else{int body=pet.health<30?0xffaaa4b1:pet.stage().equals("Winged companion")?0xff849bc9:0xff7ab9a5;if(pet.stage().equals("Winged companion")){paint.setColor(0xffb2bfdb);Path wing=new Path();wing.moveTo(9,13);wing.lineTo(1,7);wing.lineTo(4,21);wing.lineTo(11,20);canvas.drawPath(wing,paint);canvas.save();canvas.scale(-1,1,16,16);canvas.drawPath(wing,paint);canvas.restore();}paint.setColor(body);canvas.drawRect(7,10,25,24,paint);canvas.drawRect(10,6,22,26,paint);canvas.drawRect(8,3,13,11,paint);canvas.drawRect(19,3,24,11,paint);int step=pet.sleeping?0:((int)(time*4)%2);canvas.drawRect(8,24,13,27-step,paint);canvas.drawRect(19,24,24,26+step,paint);paint.setColor(0xff243c39);boolean blink=pet.sleeping||((int)(time*10)%43)<2;if(blink){canvas.drawRect(10,14,13,15,paint);canvas.drawRect(19,14,22,15,paint);}else{canvas.drawRect(10,12,13,16,paint);canvas.drawRect(19,12,22,16,paint);paint.setColor(0xfff8fff9);canvas.drawRect(10,12,11,13,paint);canvas.drawRect(19,12,20,13,paint);}paint.setColor(0xffae6578);canvas.drawRect(14,19,18,21,paint);}if(pet.sleeping){paint.setColor(0xff52657d);paint.setTextSize(5);canvas.drawText("Z",24,6+(float)Math.sin(time),paint);}else if(System.currentTimeMillis()<pet.reactionUntil){paint.setColor(0xffad5e78);canvas.drawCircle(26,5,2,paint);canvas.drawCircle(29,5,2,paint);Path heart=new Path();heart.moveTo(24,5);heart.lineTo(30,5);heart.lineTo(27,10);heart.close();canvas.drawPath(heart,paint);}canvas.restore();}
}
class CornerPet extends PetSprite implements ViewTreeObserver.OnGlobalLayoutListener {
 ViewTreeObserver observer;CornerPet(CompanionActivity host,PetState state){super(host,state);setVisibility(INVISIBLE);}
 protected void onAttachedToWindow(){super.onAttachedToWindow();observer=getViewTreeObserver();observer.addOnGlobalLayoutListener(this);post(()->check());}
 protected void onDetachedFromWindow(){if(observer!=null&&observer.isAlive())observer.removeOnGlobalLayoutListener(this);observer=null;super.onDetachedFromWindow();}
 public void onGlobalLayout(){check();}
 void check(){if(!(getParent() instanceof ViewGroup)||getWidth()==0||getHeight()==0)return;ViewGroup root=(ViewGroup)getParent();int[] location=new int[2];root.getLocationOnScreen(location);Rect corner=new Rect(location[0]+root.getWidth()-getWidth()-host.dp(8),location[1]+root.getHeight()-getHeight()-host.dp(8),location[0]+root.getWidth()-host.dp(8),location[1]+root.getHeight()-host.dp(8));boolean show=host.resumed&&!host.hidden&&!host.focusEligible()&&host.frame==null&&host.prefs.getBoolean("pet.dock",true)&&!occupied(root,corner);int visibility=show?VISIBLE:INVISIBLE;if(getVisibility()!=visibility){setVisibility(visibility);running(show);}}
 boolean occupied(View view,Rect target){if(view==this||view instanceof SeasonalOverlay||view.getVisibility()!=VISIBLE)return false;boolean text=view instanceof TextView&&((TextView)view).length()>0;boolean content=view instanceof WebView||view instanceof SurfaceView||view instanceof ImageView||view instanceof EditText||(!(view instanceof ViewGroup)&&view.getClass().getName().startsWith("local.skyfamily."));if(text||content||view.isClickable()){Rect bounds=new Rect();if(view.getGlobalVisibleRect(bounds)&&Rect.intersects(bounds,target))return true;}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)if(occupied(group.getChildAt(i),target))return true;}return false;}
}
